  "userConfig": {
    "apiKey": {
      "type": "string",
      "title": "TypeSafe API key",
      "description": "TypeSafe API key. Leave unset to use TYPESAFE_API_KEY.",
      "sensitive": true
    },
    "minTokens": {
      "type": "number",
      "title": "Minimum Bash output tokens",
      "description": "Stdout at or below this estimated token count passes through untouched. Minimum: 10000.",
      "default": 10000
    },
    "persistedOutputs": {
      "type": "boolean",
      "title": "Prune output the engine saved",
      "description": "When Bash output is too large to show inline, prune the saved file instead of leaving the model a head-of-file preview.",
      "default": true
    },
    "persistedMaxChars": {
      "type": "number",
      "title": "Budget for engine-saved output",
      "description": "Rendered character budget including omission markers and the archive footer, also capped by the native model-visible preview when available. If errors or unscored content cannot fit safely, the original result passes through. 0 disables this configured cap; the native preview cap still applies.",
      "default": 8000
    },
    "chunkLines": {
      "type": "number",
      "title": "Bash output chunk lines",
      "description": "Number of Bash output lines grouped into each Jev chunk.",
      "default": 20
    },
    "chunkChars": {
      "type": "number",
      "title": "Bash output chunk character target",
      "description": "Optional character target instead of line grouping. Preserves line boundaries after long-line splitting; adjacent chunks merge if needed to stay within 200 decisions. 0 uses chunkLines.",
      "default": 0
    },
    "diagnostics": {
      "type": "boolean",
      "title": "Log pruning decisions",
